)
stage=packet_integrity
safe_file() { test -f "$1" && test ! -L "$1" && [ "$(stat -Lc '%h' -- "$1")" = 1 ]; }
safe_file "$stage_dir/packet/development-record.json"
[ "$(sha256sum -- "$stage_dir/packet/development-record.json" | cut -d ' ' -f 1)" = ad12c20803c795d544f7a5583cd1eb3f1e362edb629e8109ce08bd9fa50017b5 ]
safe_file "$stage_dir/packet/predecessor-receipt.json"
[ "$(sha256sum -- "$stage_dir/packet/predecessor-receipt.json" | cut -d ' ' -f 1)" = b0a64e9180f0f729910b37b62978c4a3be9b6cbe8cff55a271e43d0fb5f35a4f ]
safe_file "$stage_dir/packet/candidate-receipt.json"
[ "$(sha256sum -- "$stage_dir/packet/candidate-receipt.json" | cut -d ' ' -f 1)" = 957651a59f40e138f321d90fe337dbda97cb71a269b24719ca3a24880b74e4ea ]
safe_file "$stage_dir/tools/ccgh-app-development-release.sh"
[ "$(sha256sum -- "$stage_dir/tools/ccgh-app-development-release.sh" | cut -d ' ' -f 1)" = dc705de397a2a266012b41ba05447b6b14e4af4e0a5e3f77f1fd1dd16f7da6b4 ]
safe_file "$stage_dir/tools/yard-development-contract.mjs"
[ "$(sha256sum -- "$stage_dir/tools/yard-development-contract.mjs" | cut -d ' ' -f 1)" = 1a016b65b3f828eb4659a9644372fc42eae80779a23f42c12cdd62fc45bd2e96 ]
safe_file "$stage_dir/tools/environment.go.tmpl"
[ "$(sha256sum -- "$stage_dir/tools/environment.go.tmpl" | cut -d ' ' -f 1)" = 6be4f89236ae91ddd41b106206c279c43cdc61abe0e88e7c73d551c317b6f979 ]
safe_file "$stage_dir/worker.sh"
[ "$(sha256sum -- "$stage_dir/worker.sh" | cut -d ' ' -f 1)" = 0a3f56bd2161da2aa66c3dd495eb108479ce4feafa5f37ae49a3133372d2aa36 ]
# This supervisor only records GNU timeout's result. It never calls the helper
# again or attempts rollback. Timeout owns a distinct worker process group;
# the supervisor survives group KILL so it can record an unverified outcome.
nohup setsid bash -c '
  set +x
  set -u
  umask 077
  stage_dir=$1
  if timeout --signal=TERM --kill-after=120s 480s bash -c "
    deadline_signalled=false
    trap \"deadline_signalled=true\" TERM
    bash \"\$1/worker.sh\" &
    worker_pid=\$!
    if wait \"\$worker_pid\"; then worker_status=0; else worker_status=\$?; fi
    # Keep the direct child alive after TERM, even if its worker exits early.
    # GNU timeout must reach group KILL rather than abandon live descendants.
    if [ \"\$deadline_signalled\" = true ]; then
      while :; do sleep 1; done
    fi
    exit \"\$worker_status\"
  " yard-worker-group "$stage_dir"; then deadline_status=0; else deadline_status=$?; fi
  # Cleanup also runs after whole-group KILL; no registry command is retried.
  registry_clean=true
  auth_dir="$stage_dir/registry-auth"
  if [ -e "$auth_dir" ] || [ -L "$auth_dir" ]; then
    if test -d "$auth_dir" && test ! -L "$auth_dir" && [ "$(cd -- "$auth_dir" && pwd -P)" = "$auth_dir" ]; then
      rm -rf -- "$auth_dir" || registry_clean=false
    else registry_clean=false; fi
  fi
  if [ -e "$auth_dir" ] || [ -L "$auth_dir" ]; then registry_clean=false; fi
  unset YARD_GHCR_TOKEN YARD_GHCR_USER
  printf "%s\n" "$registry_clean" > "$stage_dir/registry-cleanup-status"
  printf "%s\n" "$deadline_status" > "$stage_dir/deadline-status.tmp"
  mv -- "$stage_dir/deadline-status.tmp" "$stage_dir/deadline-status"
' yard-deadline "$stage_dir" </dev/null >"$stage_dir/worker.log" 2>&1 &
worker_pid=$!
unset YARD_GHCR_TOKEN YARD_GHCR_USER
worker_launched=true
printf '%s\n' "$worker_pid" > "$stage_dir/transport-pid.txt"
printf '{"format":"cc-gh-yard-activation-transport/v1","workerLaunched":true,"recordSha256":"%s","evidenceDirectory":"%s"}\n' "$approved" "$stage_dir"
# Observe only. Loss of SSH, Actions cancellation, or this deadline never kills,
# reruns, or rolls back the sole helper. Reconcile retained evidence if unknown.
deadline=$((SECONDS + 360))
while [ "$SECONDS" -lt "$deadline" ]; do
  if [ -f "$stage_dir/deadline-status" ] && [ ! -L "$stage_dir/deadline-status" ]; then
    if [ "$(cat -- "$stage_dir/registry-cleanup-status")" != true ]; then
      printf '{"format":"cc-gh-yard-activation-transport/v1","outcome":"unverified","registryCleanupSucceeded":false,"recordSha256":"%s"}\n' "$approved"
      exit 70
    fi
    deadline_status="$(cat -- "$stage_dir/deadline-status")"
    [[ "$deadline_status" =~ ^[0-9]{1,3}$ ]] || exit 70
    case "$deadline_status" in
      124|137|143)
        printf '{"format":"cc-gh-yard-activation-transport/v1","workerTerminal":true,"outcome":"unverified","deadlineExitCode":%s,"helperSucceeded":false,"recordSha256":"%s"}\n' "$deadline_status" "$approved"
        exit 70;;
    esac
    test -f "$stage_dir/transport-status.json"; test ! -L "$stage_dir/transport-status.json"
    status="$(cat -- "$stage_dir/transport-status.json")"
    # Emit only a strict allowlisted terminal schema produced by our worker.
    if [[ "$status" =~ ^\{\"format\":\"cc-gh-yard-activation-transport/v1\",\"workerTerminal\":true,\"stage\":\"(transport_checks|image_availability|environment_gate|release_helper|helper_completed)\",\"exitCode\":([0-9]{1,3}),\"helperSucceeded\":(true|false),\"recordSha256\":\"$approved\"\}$ ]]; then
      helper_status="${BASH_REMATCH[2]}"; helper_succeeded="${BASH_REMATCH[3]}"
      [ "$helper_status" -eq "$deadline_status" ] || exit 70
      printf '%s\n' "$status"
      if [ "$helper_status" -eq 0 ]; then [ "$helper_succeeded" = true ] || exit 70; fi
      exit "$helper_status"
    fi
    exit 70
  fi
  sleep 5
done
printf '{"format":"cc-gh-yard-activation-transport/v1","workerTerminal":false,"outcome":"unverified","recordSha256":"%s"}\n' "$approved"
exit 70
